function UIActionEquipCollectionDialog:InitData()
    self._allRegion = CfUtils.GetCf(AutoIds.IdSetting3072, "RegionEquipTypeVo", true)
end

function UIActionEquipCollectionDialog:FillSelf()
    if self._isInitScrollView then
        GameUtils.ReloadData(self.ScrollView, table.count(self._allRegion))
    else
        self.ScrollView:InitListView(table.count(self._allRegion), Bind(self, self.OnRefreshRoleIndex))
        self._isInitScrollView = true
    end
    if self._selectIndex > 1 then
        self.ScrollView:MovePanelToItemIndex(self._selectIndex - 1)
    end

    self:FillCurLabelInfo()
end

function UIActionEquipCollectionDialog:OnRefreshRoleIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(REGION_CELL_NAME)
    local data = self._allRegion[index + 1]
    local go = cell.gameObject

    ---@type UIActionEquipCollectionNode
    local scr = CfUtils.GetLuaScr(go, REGION_CELL_PATH)
    if scr then
        scr:Refresh(data, index + 1, function()
            local isUnlock = GameUtils.IsUnlocked(data.unlockType, data.unlockNum, data.unlockId)   
            if not isUnlock then 
                local err = GameUtils.GetUnlockDescr(data.unlockType, data.unlockNum, data.unlockId)   
                GameUtils.Toast(err)
                return
            end
            self:OnBtnSelect(index + 1)
        end)

        scr:FillSelect(checkNumber(self._selectIndex) == checkNumber(index + 1))  
    end

    return cell
end

function UIActionEquipCollectionDialog:OnBtnSelect(luaIndex)
    local data = self._allRegion[checkInt(luaIndex)]
    if not data then
        return
    end
    if checkInt(luaIndex) == checkInt(self._selectIndex) then
        return
    end

    -- update old
    local ind = checkInt(self._selectIndex)
    if checkNumber(ind) > 0 then
        local go = self.ScrollView:GetShownItemByItemIndex(ind - 1)
        if go then
            ---@type UIActionEquipCollectionNode
            local scr = CfUtils.GetLuaScr(go, REGION_CELL_PATH)
            if scr then
                scr:FillSelect(false)
            end
        end
    end
    
    -- update new
    self._selectIndex = checkInt(luaIndex)
    local ind = self._selectIndex
    if checkNumber(ind) > 0 then
        local go = self.ScrollView:GetShownItemByItemIndex(ind - 1)
        if go then
            ---@type UIActionEquipCollectionNode
            local scr = CfUtils.GetLuaScr(go, REGION_CELL_PATH)
            if scr then
                scr:FillSelect(true)
            end
        end
    end

    self._curEquipIndex = 0
    self:FillCurLabelInfo()
end

function UIActionEquipCollectionDialog:FillCurLabelInfo()
    local vo = self._allRegion[self._selectIndex]
    if not vo then
        return
    end

    ---@type string[]
    local t = CfUtils.Split(vo.sheetId)
    self._allType = {}

    local isShowName = #t == 1
    if #t == 1 then
        self._curSelectTypeInd = 1
    end
    local suitNameTrans = self.RightPanel.transform:Find("SuitName")
    CfUtils.SetActive(suitNameTrans, isShowName)
    CfUtils.SetActive(self.CommonTabToggleUp, not isShowName)
    if isShowName then
        local regionEquipTabVo = ActionUtils.GetRegionEquipTabVo(t[1])
        ---@type EquipFilterVo
        local equipFilterVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", regionEquipTabVo.suitId)
        CfUtils.FillText(self.TextDesc2, equipFilterVo.name)
        if suitNameTrans then
            local equipType = suitNameTrans:Find("ImgEquipType")
            CfUtils.FillImage(equipType, equipFilterVo.icon)
        end
    end

    for i, v in ipairs(t) do
        local regionEquipTabVo = ActionUtils.GetRegionEquipTabVo(v)
        ---@type EquipFilterVo
        local equipFilterVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", regionEquipTabVo.suitId)

        table.insert(self._allType, {
            type = v,
            tabVo = regionEquipTabVo,
            text = equipFilterVo.name,
            selectImgPath = equipFilterVo.pagingIcon,
            func = function(idx)
                self._curSelectTypeInd = idx
                self._curEquipIndex = 0
                self:FillEquipInfo()
            end
        })
    end

    ---@type CommonTabToggleUp
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, "Game.Behaviours.CommonTabToggleUp")
    if isNull(scr) then
        return
    end
    scr:FillToggles(self._allType, self._curSelectTypeInd)

    if self._allType[checkNumber(self._curSelectTypeInd)] then
        self:FillEquipInfo()
        self:FillCurEquipInfo()
    end
end

function UIActionEquipCollectionDialog:FillEquipInfo()
    local vo = self._allType[checkNumber(self._curSelectTypeInd)].tabVo
    local equipFilterVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", vo.suitId)
    CfUtils.FillText(self.TextDesc, equipFilterVo.desc)
    CfUtils.SetActive(self.BtnTypeNode, false)

    local t = CfUtils.Split(vo.subdirectoryId)
    if self._curEquipIndex == 0 and #t > 0 then
        self._curEquipIndex = 1
    end

    self._allEquip = {}
    for i, v in ipairs(t) do
        table.insert(self._allEquip, checkNumber(v))

        local go = self.EquipTypeChoose.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.BtnTypeNode, self.EquipTypeChoose)
            go.name = "go"..i
        end
        self:FillEquip(go, i)
        CfUtils.SetActive(go, true)
    end

    if self.EquipTypeChoose.transform.childCount > table.count(self._allEquip) then
        for i = table.count(self._allEquip) + 1, self.EquipTypeChoose.transform.childCount do
            local go = self.EquipTypeChoose.transform:Find("go"..i)
            CfUtils.SetActive(go, false)
        end
    end
end

function UIActionEquipCollectionDialog:FillEquip(go, index)
    local id = self._allEquip[checkInt(index)]
    if not go or not id then
        return
    end

    ---@type RegionEquipEntryVo
    local vo = ActionUtils.GetRegionEquipEntryVo(id)
    if not vo then
        return
    end

    local isUnlock = GameUtils.IsUnlockedSingle(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
    CfUtils.SetActive(go.transform:Find("LockGroup"), not isUnlock)
    CfUtils.FillImage(go.transform:Find("ImgEquipIcon"), vo.equipICon)
    local selectGo = go.transform:Find("Select")
    local notSelectGo = go.transform:Find("NotSelect")
    CfUtils.SetActive(selectGo, checkNumber(self._curEquipIndex) == checkNumber(index))
    CfUtils.SetActive(notSelectGo, checkNumber(self._curEquipIndex) ~= checkNumber(index))

    CfUtils.FillText(selectGo.transform:Find("TextName"), vo.equipName)
    CfUtils.FillImage(notSelectGo.transform:Find("ImgEquipIconShadow"), vo.equipShadowICon)

    SetButtonAction(go, function()
        self:OnSelectEquip(vo, index)
    end)
end

---@param vo RegionEquipEntryVo
function UIActionEquipCollectionDialog:OnSelectEquip(vo, index)
    if not vo then
        return
    end
    if checkNumber(index) == checkNumber(self._curEquipIndex) then
        return
    end

    -- update old
    local ind = checkInt(self._curEquipIndex)
    if checkNumber(ind) > 0 then
        local go = self.EquipTypeChoose.transform:Find("go"..ind)
        if go then
            local selectGo = go.transform:Find("Select")
            local notSelectGo = go.transform:Find("NotSelect")
            CfUtils.SetActive(selectGo, false)
            CfUtils.SetActive(notSelectGo, true)
        end
    end

    -- update new
    self._curEquipIndex = checkInt(index)
    local ind = self._curEquipIndex
    if checkNumber(ind) > 0 then
        local go = self.EquipTypeChoose.transform:Find("go"..ind)
        if go then
            local selectGo = go.transform:Find("Select")
            local notSelectGo = go.transform:Find("NotSelect")
            CfUtils.SetActive(selectGo, true)
            CfUtils.SetActive(notSelectGo, false)
        end
    end

    self:FillCurEquipInfo()
end

function UIActionEquipCollectionDialog:FillCurEquipInfo()
    ---@type RegionEquipEntryVo
    local vo = ActionUtils.GetRegionEquipEntryVo(self._allEquip[self._curEquipIndex])
    if not vo then
        return
    end
    CfUtils.FillText(self.TextDesc4, vo.equipJumpName)
    CfUtils.FillText(self.TextDesc3, vo.description)
end

function UIActionEquipCollectionDialog:OnBtnFontStyleButton()
    local vo = ActionUtils.GetRegionEquipEntryVo(self._allEquip[self._curEquipIndex])
    if not vo then
        return
    end

    local isUnlock = GameUtils.IsUnlockedSingle(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
    if not isUnlock then
        local err = GameUtils.GetUnlockDescr(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
        GameUtils.Toast(err)
        return
    end
    self._co = cs_coroutine.start(function()
        KCookie.Set("IsUIActionEquipCollectionDialogJump", 1)
        --cs_coroutine.yield_return(UIModule.CloseDialog(self.controller))
        local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(vo.uid)
        
        local moduleId = checkInt(row:Get("moduleID"))
        if moduleId == Constants.UITypeIds.UIActionPointMapDialog then
            local areaPointId    = checkInt(row:Get("parameter"))
            local exclusiveIds   = CfUtils.DialogGetAllArgs()
            local ActionUtils    = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            local secondaryMapVo = ActionUtils.GetRegionSecondaryMapVo(areaPointId)
            local secondMapArgs  = {id = checkInt(secondaryMapVo.regionBelong), targetPointId = areaPointId, isFromEntry = true}
            KCookie.Set("UIActionSecondMapDialogtargetPointId", areaPointId)
            CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIActionSecondMapDialog, secondMapArgs, exclusiveIds))
        else
            GoodsConfMgr:GetInstance():ExecuteJump(row, {})
        end
    end)
end

function UIActionEquipCollectionDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local initParams = CfUtils.DialogSafeParameters(self.controller)
        self._selectIndex = initParams.selectListIndex or 1
        self._curSelectTypeInd = initParams.selectTypeInd or 1
        self._curEquipIndex = initParams.selectEquipInd or 0
    end))
    return coWait
end


function UIActionEquipCollectionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local initParams = self.controller.Argument.parameters or {}
        initParams.selectListIndex = self._selectIndex
        initParams.selectTypeInd = self._curSelectTypeInd
        initParams.selectEquipInd = self._curEquipIndex

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionEquipCollectionDialog
